(() => {
'use strict';
const el=id=>document.getElementById(id);
let sourceRevision=0;
let sourceBlob=null,sourceName='',decoded=null,prepared=null,worker=null,ticket=0,voice=null,fxContext=null,musicFilter=null,musicGain=null,layerGain=null,sink=null,wavURL=null;
const report=s=>el('emotionStatus').textContent=s;
const num=(id,min,max)=>{const n=Math.max(min,Math.min(max,Number(el(id).value)||min));el(id).value=n;return n};
function controls(){el('previewEmotion').disabled=el('previewEmotionMusic').disabled=!prepared;el('prepareEmotion').disabled=!!worker;}
function invalidate(){ticket++;worker?.terminate();worker=null;stop();prepared=null;el('emotionProgress').value=0;el('emotionDownload').classList.add('hidden');if(wavURL)URL.revokeObjectURL(wavURL);wavURL=null;controls();report('Settings changed. Prepare the layer again.');}
function resetFilter(){if(musicGain){musicGain.gain.cancelScheduledValues(fxContext.currentTime);musicGain.gain.setTargetAtTime(1,fxContext.currentTime,.03)}if(musicFilter){const now=fxContext.currentTime;musicFilter.frequency.cancelScheduledValues(now);musicFilter.frequency.setTargetAtTime(el('musicTone').value==='lofi'?2400:fxContext.sampleRate*.49,now,.03)}}
function stop(){if(voice){voice.onended=null;try{voice.stop()}catch{}voice.disconnect();voice=null}resetFilter();if(typeof captureNode!=='undefined'&&captureNode&&recording&&audio.paused)captureNode.port.postMessage({active:false})}
const settingIds=['emotionKind','emotionDuration','emotionIntensity','emotionMix','pulseBpm','riseCycle','swellStart','emotionFilter','emotionEnding','musicTone','downedSpeed','downedMuffle','downedStrength'];
function settings(){return Object.fromEntries([...settingIds.map(id=>[id,el(id).value]),['emotionWithScene',el('emotionWithScene').checked]])}
function validSettings(s){for(const [id,min,max] of [['downedSpeed',50,90],['downedMuffle',0,100],['downedStrength',0,100]])if(s?.[id]!==undefined&&(!Number.isFinite(Number(s[id]))||Number(s[id])<min||Number(s[id])>max))return false;if(s?.musicTone!==undefined&&!['natural','lofi','downed'].includes(s.musicTone))return false;if(!s||typeof s.emotionWithScene!=='boolean')return false;for(const [id,choices]of [['emotionKind',['pulse','rise','swell','ambient']],['emotionFilter',['none','reveal','close']],['emotionEnding',['release','hold']]])if(!choices.includes(s[id]))return false;for(const [id,min,max]of [['emotionDuration',2,60],['emotionIntensity',0,100],['emotionMix',0,100],['pulseBpm',30,200],['riseCycle',2,30],['swellStart',0,600]])if(!Number.isFinite(Number(s[id]))||Number(s[id])<min||Number(s[id])>max)return false;return true}
window.PulseFX={
 settings,validate:validSettings,getSource,sourceRevision:()=>sourceRevision,offlineLayer(){return prepared?{...prepared,mix:Number(el('emotionMix').value)/100}:null},setTone(tone){if(tone==='downed'){el('downedSpeed').value=70;el('downedMuffle').value=75;el('downedStrength').value=70;el('emotionWithScene').checked=false;}el('musicTone').value=['lofi','downed'].includes(tone)?tone:'natural';syncDowned();resetFilter()},
 restore(s){if(!validSettings(s))return false;invalidate();settingIds.forEach(id=>el(id).value=s[id]??({musicTone:'natural',downedSpeed:70,downedMuffle:75,downedStrength:70}[id]??''));el('emotionWithScene').checked=s.emotionWithScene;syncDowned();report('Layer settings restored. Prepare the layer again to use it.');return true},
 setSource(blob,name){sourceRevision++;sourceBlob=blob;sourceName=name;decoded=null;invalidate()},
 connect(context,source,destination){fxContext=context;sink=destination;musicFilter=context.createBiquadFilter();musicFilter.type='lowpass';musicFilter.Q.value=.707;musicFilter.frequency.value=el('musicTone').value==='lofi'?2400:context.sampleRate*.49;musicGain=context.createGain();source.connect(musicFilter).connect(musicGain).connect(destination);layerGain=context.createGain();layerGain.gain.value=.25;layerGain.connect(destination)}
};
function syncDowned(){const on=el('musicTone').value==='downed';el('downedControls').classList.toggle('hidden',!on);audio.loop=on;}
setInterval(()=>{if(!musicGain||audio.paused||el('musicTone').value!=='downed')return;
 const v=PulseHeartbeat.values(audio.currentTime,Number(el('base').value),Number(el('downedMuffle').value)/100,Number(el('downedStrength').value)/100),now=fxContext.currentTime;
 for(const [param,value] of [[musicGain.gain,v.gain],[musicFilter.frequency,v.hz]]){param.cancelScheduledValues(now);param.setValueAtTime(param.value,now);param.linearRampToValueAtTime(value,now+.025)}
},25);
el('downedSpeed').oninput=()=>{el('low').value=el('downedSpeed').value;hold();aim(Number(el('downedSpeed').value)/100);};
el('revive').onclick=()=>{hold();el('musicTone').value='natural';syncDowned();el('ramp').value=4;el('fall').value=4;aim(1);if(musicGain){const now=fxContext.currentTime;for(const [param,value]of [[musicGain.gain,1],[musicFilter.frequency,fxContext.sampleRate*.49]]){param.cancelScheduledValues(now);param.setValueAtTime(param.value,now);param.linearRampToValueAtTime(value,now+4)}}report('Reviving: returning to normal speed and clear music over 4 seconds.');};
async function getSource(){if(!sourceBlob)throw Error('Load your WAV first for a source-derived swell.');if(!decoded){const decoder=new OfflineAudioContext(2,1,48000);decoded=await decoder.decodeAudioData(await sourceBlob.arrayBuffer())}return decoded}
async function swell(duration,intensity){const b=await getSource(),start=num('swellStart',0,Math.max(0,b.duration-.05));if(start>=b.duration-.02)throw Error('Choose a source position before the end of the WAV.');const sr=48000,frames=Math.round(duration*sr),offline=new OfflineAudioContext(b.numberOfChannels,frames,sr),input=offline.createBufferSource(),reverb=offline.createConvolver(),ir=offline.createBuffer(b.numberOfChannels,Math.round(Math.max(.5,duration-1)*sr),sr);let seed=42;for(let c=0;c<ir.numberOfChannels;c++){const a=ir.getChannelData(c);for(let i=0;i<a.length;i++){seed=(Math.imul(seed,1664525)+1013904223)>>>0;a[i]=(seed/4294967296*2-1)*Math.exp(-7*i/a.length)}}reverb.buffer=ir;input.buffer=b;input.connect(reverb).connect(offline.destination);input.start(0,start,Math.min(2,duration/3,b.duration-start));const wet=await offline.startRendering(),channels=[];let peak=0;for(let c=0;c<wet.numberOfChannels;c++){const data=wet.getChannelData(c).slice().reverse();for(let i=0;i<data.length;i++){data[i]*=Math.min(1,i/(sr*.04),(data.length-1-i)/(sr*.02));peak=Math.max(peak,Math.abs(data[i]))}channels.push(data)}if(peak<1e-7)throw Error('That source region is silent. Choose a different start position.');for(const ch of channels)for(let i=0;i<ch.length;i++)ch[i]*=(.25+.5*intensity)/peak;return channels;}
function filename(){return (el('emotionFilename').value.trim().replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'')||'pulse-layer')+'.wav'}
el('emotionFilename').oninput=()=>{el('emotionWav').download=filename();el('emotionWav').textContent='Download '+filename()};
el('prepareEmotion').onclick=async()=>{invalidate();const id=ticket,kind=el('emotionKind').value,duration=num('emotionDuration',2,kind==='swell'?12:60),intensity=num('emotionIntensity',0,100)/100;el('prepareEmotion').disabled=true;el('emotionProgress').removeAttribute('value');report('Preparing '+(kind==='swell'?'reverse reverb from your WAV…':'sound layer…'));try{let channels;if(kind==='ambient'){const b=await getSource();channels=await new Promise((resolve,reject)=>{worker=new Worker('ambient-worker.js');worker.onmessage=e=>e.data.error?reject(Error(e.data.error)):resolve(e.data.channels);worker.onerror=()=>reject(Error('Ambient renderer could not start.'));const channels=Array.from({length:b.numberOfChannels},(_,c)=>b.getChannelData(c).slice());worker.postMessage({channels,sampleRate:b.sampleRate,duration,start:num('swellStart',0,600)},channels.map(c=>c.buffer))});}else if(kind==='swell')channels=await swell(duration,intensity);else channels=[await new Promise((resolve,reject)=>{worker=new Worker('emotion-worker.js');worker.onmessage=e=>e.data.error?reject(Error(e.data.error)):resolve(e.data.data);worker.onerror=()=>reject(Error('Layer renderer could not start.'));worker.postMessage({kind,duration,intensity,bpm:num('pulseBpm',30,200),cycle:num('riseCycle',2,30)})})];if(id!==ticket)return;worker?.terminate();worker=null;prepared={channels,duration,kind};const bytes=PulseAssets.wav(channels,48000);wavURL=URL.createObjectURL(new Blob([bytes],{type:'audio/wav'}));el('emotionFilename').value='pulse-'+kind+'-'+duration+'s';el('emotionWav').href=wavURL;el('emotionWav').download=filename();el('emotionWav').textContent='Download '+filename();el('emotionDownload').classList.remove('hidden');el('emotionProgress').value=100;report(`Ready: ${duration}s · ${['swell','ambient'].includes(kind)?'derived from '+sourceName:'generated locally'} · 48 kHz WAV. Preview or download.`)}catch(err){if(id===ticket){worker?.terminate();worker=null;el('emotionProgress').value=0;report(err.message)}}finally{if(id===ticket){el('prepareEmotion').disabled=false;controls()}}};
async function startLayer(){if(el('musicTone').value==='downed')throw Error('Switch Music tone to Natural before playing a separate layer.');if(!prepared)throw Error('Prepare a layer first.');await captureSetup(false);stop();await fxContext.resume();const b=fxContext.createBuffer(prepared.channels.length,prepared.channels[0].length,48000);prepared.channels.forEach((data,c)=>b.copyToChannel(data,c));voice=fxContext.createBufferSource();voice.buffer=b;voice.connect(layerGain);layerGain.gain.setValueAtTime(num('emotionMix',0,100)/100,fxContext.currentTime);const now=fxContext.currentTime,d=prepared.duration,filter=el('emotionFilter').value;if(filter!=='none'){musicFilter.frequency.cancelScheduledValues(now);musicFilter.frequency.setValueAtTime(filter==='reveal'?500:18000,now);musicFilter.frequency.exponentialRampToValueAtTime(filter==='reveal'?18000:500,now+d)}const active=voice;voice.onended=()=>{active.disconnect();if(voice!==active)return;voice=null;if(el('emotionEnding').value==='release')resetFilter();if(recording&&audio.paused)captureNode.port.postMessage({active:false});report('Layer finished.'+(el('emotionEnding').value==='hold'?' Filter held; use Stop to reset.':''))};if(recording)captureNode.port.postMessage({active:true});voice.start();report('Playing layer'+(!audio.paused?' with scene music.':'.'));}
async function preview(withMusic){try{audio.pause();if(withMusic&&!sourceBlob)throw Error('Load a WAV to preview the layer with music.');await captureSetup(false);if(withMusic){audio.currentTime=0;await play();if(audio.paused)throw Error('Music playback did not start.')}await startLayer()}catch(err){report(err.message)}}
el('previewEmotion').onclick=()=>preview(false);el('previewEmotionMusic').onclick=()=>preview(true);el('stopEmotion').onclick=()=>{ticket++;worker?.terminate();worker=null;el('prepareEmotion').disabled=false;stop();el('emotionProgress').value=prepared?100:0;controls();report('Layer stopped. Music filter reset.');};
el('musicTone').onchange=()=>{syncDowned();resetFilter();report('Music tone updated. This tone is included in recorded takes, not separate layer WAVs.')};
el('emotionMix').oninput=()=>{if(layerGain)layerGain.gain.setTargetAtTime(num('emotionMix',0,100)/100,fxContext.currentTime,.03)};
for(const id of ['emotionKind','emotionDuration','emotionIntensity','pulseBpm','riseCycle','swellStart'])el(id).onchange=invalidate;
const runCuesWithLayers=el('runCues').onclick;el('runCues').onclick=async()=>{if(el('emotionWithScene').checked&&!prepared){report('Prepare the selected layer before starting the cue timeline, or uncheck Start with timeline.');return}try{await captureSetup(false);await runCuesWithLayers();if(el('emotionWithScene').checked&&!audio.paused)await startLayer()}catch(err){report('Could not start scene audio: '+err.message)}};
const resetScene=el('stop').onclick;el('stop').onclick=()=>{stop();resetScene()};el('loopWorkspace').addEventListener('click',stop);audio.addEventListener('pause',stop);audio.addEventListener('ended',stop);document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
// Scene presets suggest an effect; generation stays an explicit action.
document.querySelectorAll('#sceneTemplates button, #gameTemplates button').forEach(button=>button.addEventListener('click',()=>{const name=button.textContent;if(name==='Ambient'){el('emotionKind').value='ambient';el('emotionDuration').value=30;el('emotionFilter').value='none';el('emotionWithScene').checked=false;invalidate();report('Ambient wash selected. Preparing from your audio…');el('prepareEmotion').click();return}if(name==='Downed / Bleeding Out'){el('emotionWithScene').checked=false;el('emotionFilter').value='none';invalidate();report('Heartbeat processing is ready. Play the cue timeline; no layer preparation needed.');return}el('emotionKind').value=['Slow heartbeat','Menu','Level','Prep','Cinematic Lo-fi'].includes(name)?'pulse':['Release / recover','Credits'].includes(name)?'swell':'rise';el('emotionFilter').value=name==='Release / recover'?'close':['Menu','Level','Prep','Credits','Cinematic Lo-fi'].includes(name)?'none':'reveal';el('emotionWithScene').checked=false;invalidate();report('Suggested layer for '+name+'. Choose Prepare layer, then enable Start with cue timeline if wanted.')}));
})();
